-- 公开参考音色（官方音色库）：Seedance 视频节点可以引用的公开素材，不属于任何用户（user_id=0, source=official）。
--
-- 文件不放在平台存储里，而是在公网地址上：记录直接存音频地址 public_url 与缩略图地址 thumbnail_url，
-- 页面试听、生成时给上游的 URL 都用它，不依赖默认存储配置，新环境跑完迁移就有完整的 181 条音色。
-- 地址前缀只在下面 INSERT 里写了一处；以后换域名（如绑自定义域名）新增一个迁移，把 public_url / thumbnail_url 的前缀替换掉即可。
-- 文件在 R2 桶 video-canvas 的 official-voices/ 文件夹下（域名 img.vbing.site），与用户素材分开存放。
-- storage_key 保存对象 key（official-voices/…），只用来保证唯一和溯源，不会用来读取文件。
--
-- 官方素材库的 asset-xxx 编号已经在 storage_key 里（official-voices/fz-asset-xxx-audio.*），要溯源看它即可；
-- 音色就是一条带公网地址的素材，所有模型都按这个地址取用，不记官方素材 ID、也不分资源域。
-- 音色分类取自官方素材库标签（年龄-性别-名字），不是按名字猜的：
--   voice_age：child / teen / young / middle / older；voice_gender：male / female；
--   voice_lang：zh / en（没有官方字段：BytePlus=英文，方舟国内默认中文，其中 7 条英文声音（Chucky、Clown Man、Jigsaw、
--   Kevin McCallister、Noah、Xavier、Zayne）人工标成 en；以后出现别的英文声音也只能人工改这一列）。
ALTER TABLE assets
    ADD COLUMN public_url varchar(1024) NOT NULL DEFAULT '',
    ADD COLUMN thumbnail_url varchar(1024) NOT NULL DEFAULT '',
    ADD COLUMN voice_age varchar(16) NOT NULL DEFAULT '',
    ADD COLUMN voice_gender varchar(8) NOT NULL DEFAULT '',
    ADD COLUMN voice_lang varchar(8) NOT NULL DEFAULT '';


-- 181 条公开音色：方舟国内 80 条（中文）、BytePlus 101 条（英文）。
INSERT INTO assets (user_id, kind, storage_key, public_url, thumbnail_url, mime_type, byte_size,
                    width, height, duration_ms, source, file_name, sha256,
                    voice_age, voice_gender, voice_lang, created_at)
SELECT 0, 'audio', v.storage_key, b.base || '/' || v.storage_key, b.base || '/' || v.thumbnail_key,
       v.mime_type, v.byte_size, 0, 0, 0, 'official', v.file_name, v.sha256,
       v.voice_age, v.voice_gender, v.voice_lang, now()
FROM (SELECT 'https://img.vbing.site' AS base) b
